              const SizedBox(height: 16),
            ],
          ),
        );
      },
    );
  }

  // ── Helpers ──

  String _statusLabel(String status) {
    switch (status.toUpperCase()) {
      case 'ACCEPTED':
      case 'CONFIRMED':
        return 'Telah Dikonfirmasi';
      case 'IN_PROGRESS':
        return 'Sedang Berlangsung';
      case 'DONE':
        return 'Telah Selesai';
      case 'REJECTED':
      case 'DECLINED':
      case 'FAIL':
        return 'Ditolak / Gagal';
      case 'PENDING':
      default:
        return 'Menunggu Konfirmasi';
    }
  }

  Color _urgencyColor(String urgency) {
    final u = urgency.toLowerCase();
    if (u.contains('darurat') || u.contains('kritis') || u.contains('sangat')) return const Color(0xFFDC2626);
    if (u.contains('penting')) return const Color(0xFFD97706);
    return const Color(0xFF1D4ED8);
  }

  bool _isDateBeforeToday(String dateStr) {
    if (dateStr.isEmpty) return false;
    try {
      String cleanStr = dateStr;
      if (cleanStr.contains('T')) cleanStr = cleanStr.split('T').first;
      final d = DateTime.parse(cleanStr);
      final now = DateTime.now();
      final today = DateTime(now.year, now.month, now.day);
      return DateTime(d.year, d.month, d.day).isBefore(today);
    } catch (_) {
      return false;
    }
  }

  List<DashboardCardItem> get _displayCardItems {
    final List<DashboardCardItem> cardList = [];

    for (final order in widget.orders.where((o) => o.isActiveDashboardOrder)) {
      if (order.items.isNotEmpty) {
        for (final item in order.items) {
          final itemSt = item.status.toUpperCase();
          if (itemSt == 'DONE' || itemSt == 'CLOSE' || itemSt == 'FAIL') continue;
          if (_isDateBeforeToday(item.scheduledDate)) continue;

          String scheduleStr = item.scheduledDate;
          if (item.scheduledTimeStart.isNotEmpty) {
            scheduleStr = '${item.scheduledDate} • ${item.scheduledTimeStart}';
            if (item.scheduledTimeEnd.isNotEmpty) {
              scheduleStr += ' - ${item.scheduledTimeEnd} WIB';
            } else {
              scheduleStr += ' WIB';
            }
          }

          cardList.add(
            DashboardCardItem(
              parentOrder: order,
              title: item.itemName,
              dateSchedule: scheduleStr,
              location: item.locationName.isNotEmpty
                  ? item.locationName
                  : order.displayAddress,
              penerimaName: order.penerimaName,
              subItem: item,
            ),
          );
        }
      } else {
        final st = order.status.toUpperCase();
        if (st == 'DONE' || st == 'CLOSE' || st == 'FAIL') continue;
        if (_isDateBeforeToday(order.scheduledDate)) continue;

        cardList.add(
          DashboardCardItem(
            parentOrder: order,
            title: order.categoryName,
            dateSchedule: order.fullScheduleLabel,
            location: order.displayAddress,
            penerimaName: order.penerimaName,
            subItem: null,
          ),
        );
      }
    }

    // Sort items by scheduled date ascending (closest to current date first)
    cardList.sort((a, b) {
      final dateA = a.parentOrder.parsedDate ?? DateTime(2099);
      final dateB = b.parentOrder.parsedDate ?? DateTime(2099);
      return dateA.compareTo(dateB);
    });

    // Limit to max 5 items closest to current date
    return cardList.take(5).toList();
  }

  // ── Redesigned Premium Service Card (Umat) ──
  Widget _buildServiceCard(DashboardCardItem item) {
    final order = item.parentOrder;
    final bool isSubItemAccepted = item.subItem != null
        ? (item.subItem!.acceptedRomoId != null || item.subItem!.status.toUpperCase() == 'ACCEPTED' || item.subItem!.status.toUpperCase() == 'CONFIRMED' || item.subItem!.status.toUpperCase() == 'DONE')
        : (order.acceptedRomoId != null && order.status.toUpperCase() != 'PENDING');

    final String st = item.subItem != null
        ? (isSubItemAccepted
            ? (item.subItem!.status.toUpperCase() == 'DONE' ? 'DONE' : 'CONFIRMED')
            : 'PENDING')
        : (isSubItemAccepted
            ? (order.status.toUpperCase() == 'DONE' ? 'DONE' : 'CONFIRMED')
            : order.status.toUpperCase());

    final isKedukaan = order.categoryName.toLowerCase().contains('kedukaan');
    final urgencyColor = _urgencyColor(order.urgencyName);
    final statusLabel = _statusLabel(st);

    Color statusColor;
    IconData statusIcon;
    if (st == 'ACCEPTED' || st == 'CONFIRMED') {
      statusColor = const Color(0xFF059669);
      statusIcon = Icons.check_circle_rounded;
    } else if (st == 'DONE') {
      statusColor = const Color(0xFF2563EB);
      statusIcon = Icons.task_alt_rounded;
    } else if (st == 'REJECTED' || st == 'FAIL') {
      statusColor = const Color(0xFFDC2626);
      statusIcon = Icons.cancel_rounded;
    } else {
      statusColor = const Color(0xFFD97706);
      statusIcon = Icons.hourglass_empty_rounded;
    }

    final String romoName = item.subItem != null
        ? (item.subItem!.acceptedRomoName ?? '')
        : (order.acceptedRomoName ?? '');

    return Container(
      width: 250,
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(20),
        boxShadow: [
          BoxShadow(
            color: Colors.black.withValues(alpha: 0.06),
            blurRadius: 18,
            offset: const Offset(0, 5),
          ),
        ],
      ),
      child: ClipRRect(
        borderRadius: BorderRadius.circular(20),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            // ── Image Header ──
            SizedBox(
              height: 120,
              child: Stack(
                children: [
                  Positioned.fill(
                    child: Image.asset(
                      'assets/images/church_1.jpg',
                      fit: BoxFit.cover,
                    ),
                  ),
                  Positioned.fill(
                    child: Container(
                      decoration: BoxDecoration(
                        gradient: LinearGradient(
                          colors: [
                            Colors.black.withValues(alpha: 0.1),
                            Colors.black.withValues(alpha: 0.8),
                          ],
                          begin: Alignment.topCenter,
                          end: Alignment.bottomCenter,
                        ),
                      ),
                    ),
                  ),
                  // Category & Status Badges Row (top)
                  Positioned(
                    top: 10,
                    left: 10,
                    right: 10,
                    child: Row(
                      mainAxisAlignment: MainAxisAlignment.spaceBetween,
                      children: [
                        Flexible(
                          child: Container(
                            padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
                            decoration: BoxDecoration(
                              color: isKedukaan
                                  ? const Color(0xFF1E1B4B).withValues(alpha: 0.9)
                                  : const Color(0xFF1E3A8A).withValues(alpha: 0.9),
                              borderRadius: BorderRadius.circular(14),
                              border: Border.all(
                                color: isKedukaan
                                    ? const Color(0xFFD4AF37)
                                    : Colors.white.withValues(alpha: 0.3),
                                width: 0.8,
                              ),
                            ),
                            child: Text(
                              isKedukaan ? '✝ MISA KEDUKAAN' : '🕯️ PERMINYAKAN',
                              style: TextStyle(
                                color: isKedukaan ? const Color(0xFFF5D77D) : Colors.white,
                                fontSize: 9,
                                fontWeight: FontWeight.w800,
                                letterSpacing: 0.4,
                              ),
                              maxLines: 1,
                              overflow: TextOverflow.ellipsis,
                            ),
                          ),
                        ),
                        const SizedBox(width: 8),
                        Flexible(
                          child: Container(
                            padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
                            decoration: BoxDecoration(
                              color: statusColor,
                              borderRadius: BorderRadius.circular(14),
                            ),
                            child: Row(
                              mainAxisSize: MainAxisSize.min,
                              children: [
                                Icon(statusIcon, color: Colors.white, size: 10),
                                const SizedBox(width: 4),
                                Flexible(
                                  child: Text(
                                    statusLabel,
                                    style: const TextStyle(
                                      color: Colors.white,
                                      fontSize: 9,
                                      fontWeight: FontWeight.w800,
                                    ),
                                    maxLines: 1,
                                    overflow: TextOverflow.ellipsis,
                                  ),
                                ),
                              ],
                            ),
                          ),
                        ),
                      ],
                    ),
                  ),

                  // Location / Address (bottom of image)
                  Positioned(
                    bottom: 8,
                    left: 10,
                    right: 10,
                    child: Row(
                      children: [
                        const Icon(Icons.location_on_rounded, color: Colors.white, size: 12),
                        const SizedBox(width: 4),
                        Expanded(
                          child: Text(
                            item.location,
                            style: const TextStyle(
                              color: Colors.white,
                              fontSize: 11,
                              fontWeight: FontWeight.w600,
                              shadows: [
                                Shadow(blurRadius: 4, color: Colors.black54, offset: Offset(0, 1)),
                              ],
                            ),
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                          ),
                        ),
                      ],
                    ),
                  ),
                ],
              ),
            ),

            // ── Urgency accent strip ──
            Container(height: 3, color: urgencyColor),

            // ── Card body ──
            Padding(
              padding: const EdgeInsets.fromLTRB(12, 10, 12, 12),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  // Title: item name
                  Text(
                    item.title,
                    style: const TextStyle(
                      fontSize: 14,
                      fontWeight: FontWeight.w800,
                      color: Color(0xFF0F172A),
                      letterSpacing: -0.2,
                    ),
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                  ),
                  const SizedBox(height: 3),

                  // Subtitle: Penerima name
                  Text(
                    isKedukaan
                        ? 'Alm. ${item.penerimaName}'
                        : 'Penerima: ${item.penerimaName}',
                    style: TextStyle(
                      fontSize: 11.5,
                      fontWeight: FontWeight.w600,
                      color: isKedukaan ? const Color(0xFF7C3AED) : const Color(0xFF64748B),
                    ),
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                  ),

                  // Romo Info Badge (if assigned)
                  if (romoName.isNotEmpty) ...[
                    const SizedBox(height: 6),
                    Container(
                      padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3.5),
                      decoration: BoxDecoration(
                        color: const Color(0xFF059669).withValues(alpha: 0.08),
                        borderRadius: BorderRadius.circular(8),
                        border: Border.all(
                          color: const Color(0xFF059669).withValues(alpha: 0.2),
                          width: 0.8,
                        ),
                      ),
                      child: Row(
                        mainAxisSize: MainAxisSize.min,
                        children: [
                          const Icon(Icons.verified_user_rounded, size: 12, color: Color(0xFF059669)),
                          const SizedBox(width: 4),
                          Expanded(
                            child: Text(
                              romoName,
                              style: const TextStyle(
                                fontSize: 10.5,
                                fontWeight: FontWeight.w700,
                                color: Color(0xFF059669),
                              ),
                              maxLines: 1,
                              overflow: TextOverflow.ellipsis,
                            ),
                          ),
                        ],
                      ),
                    ),
                  ],

                  const SizedBox(height: 8),

                  // Date + Start Time + urgency pill
                  Row(
                    children: [
                      const Icon(Icons.calendar_today_outlined, size: 11, color: Color(0xFF94A3B8)),
                      const SizedBox(width: 4),
                      Expanded(
                        child: Text(
                          item.dateSchedule,
                          style: const TextStyle(
                            fontSize: 10,
                            color: Color(0xFF64748B),
                            fontWeight: FontWeight.w600,
                          ),
                          overflow: TextOverflow.ellipsis,
                        ),
                      ),
                      const SizedBox(width: 4),
                      Container(
                        padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 2),
                        decoration: BoxDecoration(
                          color: urgencyColor.withValues(alpha: 0.12),
                          borderRadius: BorderRadius.circular(5),
                        ),
                        child: Text(
                          order.urgencyName,
                          style: TextStyle(
                            fontSize: 9,
                            fontWeight: FontWeight.w700,
                            color: urgencyColor,
                          ),
                        ),
                      ),
                    ],
                  ),
                ],
              ),
            ),
          ],
        ),
      ),
    );
  }
}

class DashboardCardItem {
  final Order parentOrder;
  final String title;
  final String dateSchedule;
  final String location;
  final String penerimaName;
  final OrderItem? subItem;

  DashboardCardItem({
    required this.parentOrder,
    required this.title,
    required this.dateSchedule,
    required this.location,
    required this.penerimaName,
    this.subItem,
  });
}
